function hatchTexture() { const canvas = document.createElement('canvas'); canvas.width = 32; canvas.height = 32; const context = canvas.getContext('2d'); context.strokeStyle = '#e5b45e'; context.globalAlpha = .9; context.lineWidth = 4; for (let x = -32; x < 64; x += 12) { context.beginPath(); context.moveTo(x, 32); context.lineTo(x + 32, 0); context.stroke() } const texture = new THREE.CanvasTexture(canvas); texture.wrapS = texture.wrapT = THREE.RepeatWrapping; texture.repeat.set(3, 3); return texture }
