function buildTerrain() { if (worldObjects.terrain) world.remove(worldObjects.terrain); const group = new THREE.Group(); const geometry = new THREE.PlaneGeometry(760, 760, 80, 80); geometry.rotateX(-Math.PI / 2); const positions = geometry.attributes.position; for (let i = 0; i < positions.count; i++) positions.setY(i, terrainHeight(positions.getX(i), positions.getZ(i))); geometry.computeVertexNormals(); const terrain = new THREE.Mesh(geometry, new THREE.MeshStandardMaterial({ color: 0x50654d, roughness: 1 })); terrain.receiveShadow = true; group.add(terrain); const grid = new THREE.GridHelper(760, 19, 0xa2b696, 0x71866b); grid.material.opacity = .16; grid.material.transparent = true; group.add(grid); world.add(group); worldObjects.terrain = group }
