function droneMesh(color, id) { const group = new THREE.Group(); group.name = id; group.userData.rotors = []; const dark = new THREE.MeshStandardMaterial({ color: 0x1d2926, roughness: .5, metalness: .35 }); const shell = new THREE.Mesh(new THREE.SphereGeometry(9, 16, 10), dark); shell.scale.set(1.25, .32, .8); shell.position.y = 1; group.add(shell); const battery = new THREE.Mesh(new THREE.BoxGeometry(8, 2.3, 5), new THREE.MeshStandardMaterial({ color: 0x34443d, roughness: .7 })); battery.position.y = 3; group.add(battery); const armMaterial = new THREE.MeshStandardMaterial({ color: 0x64736c, roughness: .55, metalness: .25 }); for (const angle of [0, Math.PI / 2]) { const arm = new THREE.Mesh(new THREE.BoxGeometry(3, 2, 39), armMaterial); arm.rotation.y = angle; arm.position.y = 2; group.add(arm) } const rotorPositions = [[-16, -16], [16, -16], [-16, 16], [16, 16]]; rotorPositions.forEach(([x, z], index) => { const rotor = new THREE.Group(); rotor.position.set(x, 5, z); const hub = new THREE.Mesh(new THREE.CylinderGeometry(1.7, 1.7, 1.5, 12), new THREE.MeshStandardMaterial({ color: 0x18211f, metalness: .45, roughness: .4 })); rotor.add(hub); const bladeMaterial = new THREE.MeshBasicMaterial({ color: index % 2 ? 0xb8c9bd : 0xd7e2d6, transparent: true, opacity: .82, side: THREE.DoubleSide }); const bladeA = new THREE.Mesh(new THREE.BoxGeometry(13, .22, 1), bladeMaterial); const bladeB = new THREE.Mesh(new THREE.BoxGeometry(13, .22, 1), bladeMaterial); bladeB.rotation.y = Math.PI / 2; rotor.add(bladeA, bladeB); group.add(rotor); group.userData.rotors.push(rotor) }); const legMaterial = new THREE.MeshStandardMaterial({ color: 0x4c5c55, metalness: .35, roughness: .5 }); for (const z of [-5, 5]) { const leg = new THREE.Mesh(new THREE.CylinderGeometry(.55, .55, 9, 8), legMaterial); leg.position.set(0, -4, z); group.add(leg); const skid = new THREE.Mesh(new THREE.CylinderGeometry(.65, .65, 19, 8), legMaterial); skid.rotation.z = Math.PI / 2; skid.position.set(0, -8, z); group.add(skid) } const gimbal = new THREE.Mesh(new THREE.SphereGeometry(2.8, 14, 10), new THREE.MeshStandardMaterial({ color: 0x111817, metalness: .55, roughness: .3 })); gimbal.position.set(0, -3, -6); group.add(gimbal); const lens = new THREE.Mesh(new THREE.CircleGeometry(1.25, 16), new THREE.MeshBasicMaterial({ color: 0x6fc4d5 })); lens.position.set(0, -3, -8.4); lens.rotation.x = Math.PI; group.add(lens); const beacon = new THREE.Mesh(new THREE.SphereGeometry(2.2, 12, 8), new THREE.MeshBasicMaterial({ color })); beacon.position.y = 7; group.add(beacon); const ring = new THREE.Mesh(new THREE.RingGeometry(15, 17, 32), new THREE.MeshBasicMaterial({ color, transparent: true, opacity: .58, side: THREE.DoubleSide })); ring.rotation.x = -Math.PI / 2; ring.position.y = -44; group.add(ring); const label = makeLabel(id, color); label.position.y = 16; label.position.x = -18; group.add(label); return group }
function clearLayerObjects() { worldObjects.priority.forEach(object => world.remove(object)); worldObjects.coverage.forEach(object => world.remove(object)); worldObjects.priority = []; worldObjects.coverage = []; if (worldObjects.noFly) world.remove(worldObjects.noFly); worldObjects.noFly = null }
function buildLayers() { clearLayerObjects(); cells().forEach((cell, index) => { const point = local(cell); const color = [0xb95045, 0xb8874b, 0x6e916d, 0x8a9c70][index % 4]; const priority = new THREE.Mesh(new THREE.CircleGeometry(Math.sqrt((cell.area_m2 || 25000) / Math.PI) * SCENE_SCALE, 32), new THREE.MeshBasicMaterial({ color, transparent: true, opacity: .22, depthWrite: false })); priority.rotation.x = -Math.PI / 2; priority.position.set(point.x, terrainHeight(point.x, point.z) + .7, point.z); world.add(priority); worldObjects.priority.push(priority); const coverage = new THREE.Mesh(new THREE.CircleGeometry(28, 32), new THREE.MeshBasicMaterial({ color: 0x8bb99a, transparent: true, opacity: .13, depthWrite: false })); coverage.rotation.x = -Math.PI / 2; coverage.position.set(point.x, terrainHeight(point.x, point.z) + 1, point.z); world.add(coverage); worldObjects.coverage.push(coverage); const label = makeLabel(`${cell.id} · P${cell.priority || '-'}`, `#${new THREE.Color(color).getHexString()}`); label.position.set(point.x - 17, terrainHeight(point.x, point.z) + 6, point.z - 20); world.add(label) }); const noFly = (state.data?.no_fly || [])[0]; if (noFly) { const point = local(noFly); const radius = Number(noFly.radius || .0007) * METER_LAT * SCENE_SCALE; const material = new THREE.MeshBasicMaterial({ map: hatchTexture(), color: 0xd89d4b, transparent: true, opacity: .55, side: THREE.DoubleSide, depthWrite: false }); const shape = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, Number(noFly.height || 70) * SCENE_SCALE, 32, 1, true), material); shape.position.set(point.x, Number(noFly.height || 70) * SCENE_SCALE / 2, point.z); world.add(shape); worldObjects.noFly = shape; const label = makeLabel('NO-FLY', '#e5b45e'); label.position.set(point.x - 18, Number(noFly.height || 70) * SCENE_SCALE + 8, point.z); world.add(label) } }
