function fromDelta(origin, east, north) { return { lat: origin.lat + north / METER_LAT, lon: origin.lon + east / lonMeters(origin.lat), altitude: origin.altitude || 0 } }
function pointInside(point, polygon) { let inside = false; for (let index = 0, previous = polygon.length - 1; index < polygon.length; previous = index++) { const a = polygon[index]; const b = polygon[previous]; if ((a.lon > point.lon) !== (b.lon > point.lon) && point.lat < (b.lat - a.lat) * (point.lon - a.lon) / (b.lon - a.lon) + a.lat) inside = !inside } return inside }
function flockStepClient(dt) { const drones = [...state.simDrones.values()]; const radius = 45; const polygon = state.data?.no_fly_polygon || null; for (const drone of drones) { const route = state.routes[drone.drone_id] || []; const index = Math.min(Math.floor(state.time / 18), Math.max(route.length - 1, 0)); const target = route[Math.min(index + 1, Math.max(route.length - 1, 0))] || route[index] || drone; const goalDelta = localDelta(drone, target); const goalDistance = Math.hypot(goalDelta.east, goalDelta.north); const goalSpeed = goalDistance ? Math.min(20, goalDistance / Math.max(dt, .01)) : 0; const goal = goalDistance ? { east: goalDelta.east / goalDistance * goalSpeed, north: goalDelta.north / goalDistance * goalSpeed } : { east: 0, north: 0 }; let sep = { east: 0, north: 0 }; let align = { east: 0, north: 0 }; let cohesion = { east: 0, north: 0 }; let count = 0; for (const other of drones) { if (other === drone) continue; const delta = localDelta(drone, other); const distance = Math.hypot(delta.east, delta.north); if (distance > radius) continue; count += 1; const safeDistance = distance || 1; sep.east -= delta.east / safeDistance * (radius - distance) / radius; sep.north -= delta.north / safeDistance * (radius - distance) / radius; align.east += other.velocity.east - drone.velocity.east; align.north += other.velocity.north - drone.velocity.north; cohesion.east += delta.east; cohesion.north += delta.north } if (count) { align.east /= count; align.north /= count; cohesion.east /= count; cohesion.north /= count } const weights = { goal: 12, separation: 2.5, alignment: .25, cohesion: .15 }; let velocity = { east: (goal.east * weights.goal + sep.east * 20 * weights.separation + align.east * weights.alignment + cohesion.east * weights.cohesion) / (weights.goal + weights.separation + weights.alignment + weights.cohesion), north: (goal.north * weights.goal + sep.north * 20 * weights.separation + align.north * weights.alignment + cohesion.north * weights.cohesion) / (weights.goal + weights.separation + weights.alignment + weights.cohesion) }; const smoothing = Math.min(1, dt * 3); velocity = { east: drone.velocity.east + (velocity.east - drone.velocity.east) * smoothing, north: drone.velocity.north + (velocity.north - drone.velocity.north) * smoothing }; const speed = Math.hypot(velocity.east, velocity.north); if (speed > 20) { velocity.east = velocity.east / speed * 20; velocity.north = velocity.north / speed * 20 } let proposed = fromDelta(drone, velocity.east * dt, velocity.north * dt); if (polygon && pointInside(proposed, polygon)) { velocity.east = 0; velocity.north = 0; proposed = { ...drone } } drone.velocity = velocity; drone.lat = proposed.lat; drone.lon = proposed.lon } }
function moveDrones(dt) { if (state.mode === 'swarm') flockStepClient(dt); const active = state.mode === 'swarm' ? [...state.simDrones.values()] : [{ ...getSinglePoint(), drone_id: 'single' }]; active.forEach((drone, index) => { const mesh = worldObjects.drones.get(state.mode === 'swarm' ? drone.drone_id : 'single'); if (!mesh) return; const point = local(drone); const y = terrainHeight(point.x, point.z); mesh.visible = true; mesh.position.set(point.x, y + 55 + Math.sin(performance.now() * .004 + index) * .7, point.z); const route = state.mode === 'swarm' ? (Array.isArray(state.routes[drone.drone_id]) ? state.routes[drone.drone_id] : []) : effectiveSingleRoute(); const next = route[Math.min(Math.floor(state.time / 18) + 1, Math.max(route.length - 1, 0))]; if (next) { const target = local(next); mesh.lookAt(target.x, y + 55, target.z) } mesh.userData.rotors?.forEach((rotor, rotorIndex) => { rotor.rotation.y += dt * (34 + rotorIndex * 2) }); if (index === 0) { droneCamera.position.set(point.x + 48, y + 62, point.z + 48); droneCamera.lookAt(point.x, y + 8, point.z); $('cameraReadout').textContent = `${state.running ? 'AIRBORNE' : 'PARKED'} · ${sensorTitle(state.activeSensor)} · ${drone.lat.toFixed(5)}, ${drone.lon.toFixed(5)}` } }) }
function frameMainView() { const points = [homePoint(), ...cells()]; if (!points.length) return; const xs = points.map(point => local(point).x); const zs = points.map(point => local(point).z); orbitTarget.set((Math.min(...xs) + Math.max(...xs)) / 2, 20, (Math.min(...zs) + Math.max(...zs)) / 2); orbit.radius = Math.max(360, Math.min(760, Math.max(Math.max(...xs) - Math.min(...xs), Math.max(...zs) - Math.min(...zs)) * 1.8)); updateOrbit() }
function updateOrbit() { camera.position.set(orbitTarget.x + Math.sin(orbit.theta) * Math.sin(orbit.phi) * orbit.radius, orbitTarget.y + Math.cos(orbit.phi) * orbit.radius, orbitTarget.z + Math.cos(orbit.theta) * Math.sin(orbit.phi) * orbit.radius); camera.lookAt(orbitTarget) }
function updateRenderers() { const viewport = $('viewport').getBoundingClientRect(); renderer.setSize(Math.max(viewport.width, 1), Math.max(viewport.height, 1), false); camera.aspect = Math.max(viewport.width, 1) / Math.max(viewport.height, 1); camera.updateProjectionMatrix(); const cameraRect = $('cameraViewport').getBoundingClientRect(); cameraRenderer.setSize(Math.max(cameraRect.width, 1), Math.max(cameraRect.height, 1), false); droneCamera.aspect = Math.max(cameraRect.width, 1) / Math.max(cameraRect.height, 1); droneCamera.updateProjectionMatrix() }
function drawMinimap() { if (!state.data) return; const rect = miniCanvas.getBoundingClientRect(); const dpr = Math.min(window.devicePixelRatio || 1, 2); miniCanvas.width = Math.max(rect.width * dpr, 1); miniCanvas.height = Math.max(rect.height * dpr, 1); miniContext.setTransform(dpr, 0, 0, dpr, 0, 0); miniContext.clearRect(0, 0, rect.width, rect.height); miniContext.fillStyle = '#132016'; miniContext.fillRect(0, 0, rect.width, rect.height); const points = [homePoint(), ...cells(), ...(state.data.detections || [])]; const positions = points.map(point => local(point)); const minX = Math.min(...positions.map(point => point.x), -100) - 100; const maxX = Math.max(...positions.map(point => point.x), 100) + 100; const minZ = Math.min(...positions.map(point => point.z), -100) - 100; const maxZ = Math.max(...positions.map(point => point.z), 100) + 100; const scale = Math.min(rect.width / Math.max(maxX - minX, 1), rect.height / Math.max(maxZ - minZ, 1)); const screen = point => { const localPoint = local(point); return { x: (localPoint.x - minX) * scale + (rect.width - (maxX - minX) * scale) / 2, y: (localPoint.z - minZ) * scale + (rect.height - (maxZ - minZ) * scale) / 2 } }; cells().forEach((cell, index) => { const point = screen(cell); miniContext.fillStyle = `${state.mode === 'swarm' ? colorForDrone(state.data.sectors?.find(sector => sector.cell_id === cell.id)?.owning_drone_id, index) : index === 0 ? '#d86a55' : '#708d68'}66`; miniContext.beginPath(); miniContext.arc(point.x, point.y, 18, 0, Math.PI * 2); miniContext.fill(); miniContext.fillStyle = '#d9e5d0'; miniContext.font = '8px ui-monospace, monospace'; miniContext.fillText(cell.id, point.x + 8, point.y - 7) }); if (state.mode === 'single') { miniContext.strokeStyle = '#e0c97d'; miniContext.lineWidth = 2; miniContext.beginPath(); state.route.forEach((routePoint, index) => { const point = screen(routePoint); if (!index) miniContext.moveTo(point.x, point.y); else miniContext.lineTo(point.x, point.y) }); miniContext.stroke() } const home = screen(homePoint()); miniContext.fillStyle = '#edd18d'; miniContext.fillRect(home.x - 4, home.y - 4, 8, 8); (state.data.detections || []).forEach(detection => { const point = screen(detection); miniContext.fillStyle = '#ed6255'; miniContext.beginPath(); miniContext.arc(point.x, point.y, 5, 0, Math.PI * 2); miniContext.fill() }); const dronePoints = state.mode === 'swarm' ? [...state.simDrones.values()] : [getSinglePoint()]; dronePoints.forEach((drone, index) => { const point = screen(drone); miniContext.fillStyle = state.mode === 'swarm' ? colorForDrone(drone.drone_id, index) : '#b9ef9b'; miniContext.beginPath(); miniContext.arc(point.x, point.y, 6, 0, Math.PI * 2); miniContext.fill() }); $('minimapReadout').textContent = state.mode === 'swarm' ? `${state.data.drones?.length || 0} DRONES · OWNERSHIP / COVERAGE · PLANNING ONLY` : `${getSinglePoint().lat.toFixed(5)}, ${getSinglePoint().lon.toFixed(5)} · ${state.terrain?.source === 'dem' ? 'DEM' : 'SIM'} MAP` }

function renderDetections() { const detections = state.data?.detections || []; $('detectionCount').textContent = `${detections.length} CANDIDATE${detections.length === 1 ? '' : 'S'}`; const list = $('detectionList'); list.replaceChildren(); if (!detections.length) { list.innerHTML = '<div class="empty-state">No candidate has been accepted.</div>'; return } detections.forEach(detection => { const row = document.createElement('article'); row.className = 'detection-row'; const title = document.createElement('strong'); title.textContent = `${String(detection.label || 'CANDIDATE').toUpperCase()} · ${Math.round((detection.confidence || 0) * 100)}%`; const meta = document.createElement('span'); meta.textContent = `${sensorTitle(detection.band || 'rgb')} · ${Number(detection.lat).toFixed(6)}, ${Number(detection.lon).toFixed(6)}${detection.track_id ? ` · ${detection.track_id}` : ''}`; const detail = document.createElement('small'); detail.textContent = `${detection.evidence || 'No evidence note'} · ${detection.source_frame || 'unknown frame'}`; row.append(title, meta, detail); if (state.mode === 'single') { const action = document.createElement('button'); action.className = 'quiet-button'; action.type = 'button'; action.textContent = detection.investigated ? 'INVESTIGATED' : 'MARK INVESTIGATED'; action.disabled = Boolean(detection.investigated); action.onclick = () => investigateDetection(detection); row.append(action) } list.append(row) }) }
function renderTracks() { const tracks = state.data?.tracks || []; $('trackingModeBadge').textContent = String(state.data?.tracking_mode || 'nearest_decay').toUpperCase().replace('_', '-'); const list = $('tracksList'); list.replaceChildren(); $('tracksEmpty').hidden = tracks.length > 0; if (!tracks.length) return; tracks.forEach(track => { const row = document.createElement('article'); row.className = 'track-row'; row.dataset.trackId = track.track_id; const title = document.createElement('strong'); title.textContent = track.track_id; const meta = document.createElement('span'); meta.textContent = `CONFIDENCE ${Math.round((track.confidence || 0) * 100)}% · ${track.detection_count || 0} CORROBORATING DETECTIONS`; const detail = document.createElement('small'); detail.textContent = `${Number(track.lat).toFixed(6)}, ${Number(track.lon).toFixed(6)} · ${String(track.tracking_mode || state.data?.tracking_mode || 'nearest_decay').toUpperCase().replace('_', '-')}`; row.append(title, meta, detail); list.append(row) }) }
function renderSwarm() { const initialized = Boolean(state.data?.initialized !== false && state.data?.drones?.length); $('swarmEmpty').hidden = initialized; $('swarmRows').replaceChildren(); $('initSwarm').hidden = initialized; if (!initialized) return; const sectors = new Map((state.data.sectors || []).map(sector => [sector.cell_id, sector])); state.data.drones.forEach((drone, index) => { const row = document.createElement('article'); row.className = 'swarm-row'; row.dataset.droneId = drone.drone_id; row.style.setProperty('--drone-color', colorForDrone(drone.drone_id, index)); const id = document.createElement('strong'); id.textContent = drone.drone_id; const status = document.createElement('span'); status.className = `drone-status ${drone.status}`; status.textContent = drone.status === 'investigating' ? 'INVESTIGATE' : drone.status === 'returning' ? 'RETURN TO BASE' : drone.status.toUpperCase(); const sector = document.createElement('span'); sector.textContent = drone.assigned_sector_id || (sectors.get(drone.assigned_sector_id)?.owner_status || 'IDLE'); const battery = document.createElement('span'); battery.textContent = `${Math.round(drone.battery_percent)}%`; row.append(id, status, sector, battery); $('swarmRows').append(row) }) }
function setModePanels() { const swarm = state.mode === 'swarm'; $('missionCard').hidden = swarm; $('swarmControlPanel').hidden = !swarm; $('tracksPanel').hidden = !swarm; $('modeToggle').textContent = swarm ? 'SINGLE MODE' : 'ENTER SWARM MODE'; $('testEvent').textContent = swarm ? 'SIMULATE PASS' : 'TEST SENSOR'; $('airspaceBadge').textContent = swarm ? 'SWARM · PLANNING ONLY' : 'SIMULATION ONLY' }
function applySingle(payload, fit = false) { state.mode = 'single'; state.data = payload; state.singleData = payload; state.route = Array.isArray(payload.waypoints) ? payload.waypoints.slice() : []; state.routes = {}; state.satellite = Object.prototype.hasOwnProperty.call(payload, 'satellite_context') ? payload.satellite_context : state.satellite; state.detected = (payload.detections || []).some(detection => !detection.investigated); setModePanels(); $('missionId').textContent = payload.mission_id || 'MISSION'; updateDataSourceStatus(); buildTerrain(); buildLayers(); updateRoute(); updateDetections(); setupDroneMeshes(); renderDetections(); renderTracks(); if (fit) frameMainView() }
function applySwarm(payload, fit = false) { state.mode = 'swarm'; state.data = { ...payload, home: payload.home || { lat: 30.362, lon: 78.082, altitude: 1200 }, cells: payload.cells || (payload.sectors || []).map(sector => ({ id: sector.cell_id, lat: sector.lat || 30.362, lon: sector.lon || 78.082, priority: sector.priority, likelihood: sector.likelihood, coverage_fraction: sector.coverage_fraction })), no_fly: payload.no_fly || [] }; state.swarmData = state.data; state.routes = payload.waypoints || {}; state.route = []; state.satellite = null; setSimDrones(); setModePanels(); $('missionId').textContent = payload.mission_id || 'SWARM NOT INITIALIZED'; updateDataSourceStatus(); buildTerrain(); buildLayers(); updateRoute(); updateDetections(); setupDroneMeshes(); renderSwarm(); renderTracks(); renderDetections(); if (fit) frameMainView() }
function applyPayload(payload, fit = false) { if (payload?.mode === 'swarm') applySwarm(payload, fit); else applySingle(payload, fit) }
async function sendFrame(file, sensor, frameId, filename) { const requestId = ++state.latestRequestId; const form = new FormData(); form.append('image', file, filename || `${frameId}.jpg`); form.append('sensor', sensor); form.append('metadata', JSON.stringify({ frame_id: frameId, lat: homePoint().lat, lon: homePoint().lon, altitude_m: homePoint().altitude, ground_sample_distance_m: .25, source_type: sensor, crs: 'EPSG:4326', metadata_quality: 'simulated-camera-metadata' })); const payload = await requestJson('/api/frames/detect', { method: 'POST', body: form }); if (requestId >= state.latestAppliedRequestId) { state.latestAppliedRequestId = requestId; applySingle(payload) } }
async function simulatePass() { const target = state.data?.cells?.[0] || homePoint(); state.passCount += 1; const payload = { detections: [{ id: `simulated-person-${state.passCount}`, lat: target.lat, lon: target.lon, altitude: target.altitude || 0, confidence: .72, band: 'rgb', source_frame: `swarm-pass-${state.passCount}`, evidence: 'simulated pass; investigation cue' }] }; try { const response = await requestJson('/api/swarm/telemetry', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) }); applySwarm(response); setStatus(`SIMULATED PASS ${state.passCount} · TRACK ASSOCIATED`, 'success') } catch (error) { const existing = state.data?.tracks?.[0]; const track = existing || { track_id: 'TRK-001', lat: target.lat, lon: target.lon, confidence: .72, detection_count: 0, tracking_mode: 'nearest_decay' }; track.detection_count = (track.detection_count || 0) + 1; state.data = { ...state.data, detections: [{ id: track.track_id, track_id: track.track_id, lat: target.lat, lon: target.lon, confidence: track.confidence, label: 'simulated candidate', band: 'rgb' }], tracks: [track] }; renderTracks(); renderDetections(); setStatus('SIMULATED PASS · LOCAL REPLAY', 'success') } }
async function triggerTest() { if (state.mode === 'swarm') { await simulatePass(); return } if (state.detecting || state.busy || state.activeSensor === 'change') return; state.detecting = true; $('testEvent').disabled = true; const frameId = nextFrameId(`test-${state.activeSensor}`); try { const canvas = document.createElement('canvas'); canvas.width = 128; canvas.height = 96; const context = canvas.getContext('2d'); context.fillStyle = '#111'; context.fillRect(0, 0, 128, 96); context.fillStyle = '#f5f5f5'; context.fillRect(57, 30, 14, 36); const blob = await new Promise(resolve => canvas.toBlob(resolve, 'image/jpeg', .9)); await sendFrame(blob, state.activeSensor, frameId); $('sensorState').textContent = `${sensorTitle(state.activeSensor)} ANALYSIS COMPLETE`; setStatus('TEST FRAME COMPLETE', 'success') } catch (error) { setStatus(error.message, 'error') } finally { state.detecting = false; $('testEvent').disabled = false } }
async function analyzeFrame(file) { if (!file || state.busy) return; state.busy = 'frame'; const sensor = state.activeSensor; $('loadFrame').disabled = true; try { await sendFrame(file, sensor, nextFrameId(sensor), file.name); $('cameraMode').textContent = `${sensorTitle(sensor)} INPUT LOADED`; $('sensorState').textContent = `${sensorTitle(sensor)} ANALYSIS COMPLETE`; setStatus(`${sensorTitle(sensor)} ANALYSIS COMPLETE`, 'success') } catch (error) { setStatus(error.message, 'error') } finally { state.busy = null; $('loadFrame').disabled = false; $('frameInput').value = '' } }
async function analyzeChange() { if (!state.changeFiles.previous || !state.changeFiles.current || state.busy) return; state.busy = 'change'; $('loadChange').disabled = true; try { const form = new FormData(); form.append('previous', state.changeFiles.previous); form.append('current', state.changeFiles.current); form.append('metadata', JSON.stringify({ frame_id: nextFrameId('change'), lat: homePoint().lat, lon: homePoint().lon, altitude_m: homePoint().altitude, source_type: 'change' })); const payload = await requestJson('/api/change-detection', { method: 'POST', body: form }); applySingle(payload, true); const registration = payload.change_registration; $('cameraMode').textContent = 'CHANGE PASS LOADED'; $('sensorState').textContent = registration?.registered ? `REGISTERED · ${Math.round((registration.score || 0) * 100)}% MATCH` : 'REGISTRATION FALLBACK'; setStatus(registration?.registered ? 'CHANGE DETECTION COMPLETE · PASSES REGISTERED' : 'CHANGE DETECTION COMPLETE · CHECK REGISTRATION', registration?.registered ? 'success' : 'error') } catch (error) { setStatus(error.message, 'error') } finally { state.busy = null; $('loadChange').disabled = false; state.changeFiles = { previous: null, current: null }; $('previousChangeInput').value = ''; $('currentChangeInput').value = '' } }
async function loadDem(file) { if (!file || state.busy) return; state.busy = 'dem'; try { const form = new FormData(); form.append('dem', file, file.name); const payload = await requestJson('/api/terrain/load', { method: 'POST', body: form }); state.terrain = payload.terrain; applyPayload(payload.mission, true); setStatus('DEM LOADED · TERRAIN ROUTING ACTIVE', 'success') } catch (error) { setStatus(error.message, 'error') } finally { state.busy = null; $('demInput').value = '' } }
async function loadSatellite(file) { if (!file || state.busy) return; state.busy = 'satellite'; try { const form = new FormData(); form.append('image', file, file.name); form.append('metadata', JSON.stringify({ source_type: 'satellite' })); const payload = await requestJson('/api/satellite/context', { method: 'POST', body: form }); state.satellite = payload.context; applySingle(payload.mission, true); setStatus('SATELLITE CONTEXT READY', 'success') } catch (error) { setStatus(error.message, 'error') } finally { state.busy = null; $('satelliteInput').value = '' } }
async function analyzeDataset(file) { if (!file || state.busy) return; state.busy = 'dataset'; try { const form = new FormData(); form.append('dataset', file); const payload = await requestJson('/api/dataset/analyze', { method: 'POST', body: form }); applySingle(payload, true); setStatus('DATASET ANALYSIS COMPLETE', 'success') } catch (error) { setStatus(error.message, 'error') } finally { state.busy = null; $('datasetInput').value = '' } }
function selectSensor(sensor) { state.activeSensor = sensor; const card = document.querySelector('.camera-card'); card.classList.remove('band-rgb', 'band-thermal', 'band-multispectral', 'band-change'); card.classList.add(`band-${sensor}`); document.querySelectorAll('[data-sensor]').forEach(button => { const selected = button.dataset.sensor === sensor; button.classList.toggle('active', selected); button.setAttribute('aria-selected', String(selected)) }); $('sensorState').textContent = sensor === 'change' ? 'SELECT TWO PASSES TO COMPARE' : `${sensorTitle(sensor)} ANALYSIS READY`; $('loadFrame').hidden = sensor === 'change' || state.mode === 'swarm'; $('loadChange').hidden = sensor !== 'change'; $('testEvent').hidden = sensor === 'change'; $('cameraMode').textContent = sensor === 'change' ? 'SUCCESSIVE PASS MODE' : `${sensorTitle(sensor)} VIEW`; $('cameraBandOverlay').textContent = sensor === 'change' ? 'SUCCESSIVE PASS MODE' : `${sensorTitle(sensor)} · ${sensor === 'thermal' ? 'HEAT SIGNATURE' : sensor === 'multispectral' ? 'VEGETATION / CONTRAST' : 'VISIBLE LIGHT'}` }
function initLayerButtons() { const bindings = [['toggleHeat', 'heat', worldObjects.priority], ['toggleCoverage', 'coverage', worldObjects.coverage], ['toggleNfz', 'nfz', [worldObjects.noFly]]]; bindings.forEach(([id, key, objects]) => { $(id).onclick = () => { state.layers[key] = !state.layers[key]; objects.forEach(object => { if (object) object.visible = state.layers[key] }); $(id).classList.toggle('selected', state.layers[key]); $(id).setAttribute('aria-pressed', String(state.layers[key])); setStatus(`${key.toUpperCase()} LAYER ${state.layers[key] ? 'ON' : 'OFF'}`) } }) }
async function enterSwarm() { if (state.mode === 'single') { try { const payload = await requestJson('/api/swarm'); applySwarm(payload); setStatus(payload.initialized ? 'SWARM CONTROL READY · PLANNING ONLY' : 'SWARM MODE · INITIALIZE SIMULATION', 'success') } catch { applySwarm({ mode: 'swarm', initialized: false, drones: [], sectors: [], cells: [], detections: [], tracks: [], waypoints: {}, mission_id: state.data?.mission_id }); setStatus('SWARM MODE · API NOT INITIALIZED', 'error') } } else { applySingle(state.singleData || { mission_id: 'MISSION', home: homePoint(), cells: [], waypoints: [] }); setStatus('SINGLE MODE · SIMULATION ONLY') } }
async function initSwarm() { try { const payload = await requestJson('/api/swarm/init', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ drone_count: 4 }) }); state.running = true; applySwarm(payload, true); setStatus('SWARM INITIALIZED · PLANNING ONLY', 'success') } catch (error) { setStatus(error.message, 'error') } }
function updateUi() { const routeCount = state.mode === 'swarm' ? Math.max(...Object.values(state.routes).map(route => route.length), 1) : state.route.length; const duration = Math.max(routeCount * 18, 1); const progress = Math.min(state.time / duration, 1); const phase = state.mode === 'swarm' ? (state.data?.initialized === false ? 'SWARM STANDBY' : 'COORDINATED SEARCH') : state.time < 8 && state.running ? 'TAKEOFF / CLIMB' : state.detected ? 'INVESTIGATE CANDIDATE' : state.time > duration - 18 && state.running ? 'RETURN TO BASE' : state.running ? 'SEARCH SECTOR' : state.time ? 'PAUSED' : 'STANDBY'; $('missionState').textContent = state.running ? 'LIVE' : 'PAUSED'; $('airspaceBadge').textContent = state.mode === 'swarm' ? 'SWARM · PLANNING ONLY' : 'SIMULATION ONLY'; const battery = state.mode === 'swarm' ? Math.round((state.data?.drones || []).reduce((sum, drone) => sum + Number(drone.battery_percent || 0), 0) / Math.max((state.data?.drones || []).length, 1)) : Math.max(36, Math.round(100 - state.time / (duration + 12) * 58)); $('battery').textContent = `${battery}%`; $('coverage').textContent = `${Math.round((state.mode === 'swarm' ? Number(state.data?.swarm_coverage_fraction || 0) : progress) * 100)}%`; $('elapsed').textContent = formatClock(state.time); $('batteryLine').textContent = `${battery}%`; $('batteryMeter').style.width = `${battery}%`; $('action').textContent = phase === 'STANDBY' ? 'READY TO SEARCH' : phase; $('actionDetail').textContent = state.mode === 'swarm' ? 'Flocking spaces simulated aircraft while each route remains sector-bound.' : 'Following the ranked route across the search sectors.'; $('nextAction').textContent = state.mode === 'swarm' ? 'Review swarm control' : state.running ? `Continue ${state.route[Math.min(Math.floor(state.time / 18), state.route.length - 1)]?.cell_id || 'route'}` : 'Launch aircraft'; $('statusChip').textContent = state.mode === 'swarm' ? 'PLANNING' : state.detected ? 'REVIEW' : state.running ? 'RUNNING' : 'READY'; $('altitude').textContent = '35 m'; $('speed').textContent = state.running ? '8.0 m/s' : '0.0 m/s'; $('activeLeg').textContent = state.mode === 'swarm' ? 'MULTI-SECTOR' : state.route[Math.min(Math.floor(state.time / 18), state.route.length - 1)]?.cell_id || 'HOME → RIDGE-01'; $('reserve').textContent = state.mode === 'swarm' ? 'SIMULATED' : `${Math.max(8, Math.round(18 - state.time / 60))} min`; $('phaseLabel').textContent = phase; $('timelineProgress').style.width = `${progress * 100}%`; renderSwarm(); renderTracks(); drawMinimap() }
function initInput() { const element = renderer.domElement; element.addEventListener('pointerdown', event => { orbit.down = true; orbit.x = event.clientX; orbit.y = event.clientY; element.setPointerCapture(event.pointerId) }); element.addEventListener('pointerup', () => { orbit.down = false }); element.addEventListener('pointermove', event => { if (!orbit.down) return; orbit.theta -= (event.clientX - orbit.x) * .006; orbit.phi = THREE.MathUtils.clamp(orbit.phi + (event.clientY - orbit.y) * .006, .32, 1.48); orbit.x = event.clientX; orbit.y = event.clientY }); element.addEventListener('wheel', event => { event.preventDefault(); orbit.radius = THREE.MathUtils.clamp(orbit.radius + event.deltaY * .22, 300, 900) }, { passive: false }); window.addEventListener('keydown', event => { if (event.target.matches('input, select, textarea')) return; if (event.key.toLowerCase() === 'r') { orbit = { theta: .7, phi: 1.02, radius: 520, down: false, x: 0, y: 0 }; frameMainView() } }); window.addEventListener('resize', updateRenderers) }
function initButtons() { $('resetView').onclick = () => { orbit = { theta: .7, phi: 1.02, radius: 520, down: false, x: 0, y: 0 }; frameMainView() }; $('modeToggle').onclick = enterSwarm; $('initSwarm').onclick = initSwarm; $('toggleMission').onclick = () => { state.running = !state.running; state.lastAnimationMs = performance.now(); $('toggleMission').textContent = state.running ? 'PAUSE MISSION' : 'RESUME MISSION'; setStatus(state.running ? 'MISSION RUNNING · SIMULATION MOVING' : 'MISSION PAUSED') }; $('restartMission').onclick = async () => { try { const payload = await requestJson(state.mode === 'swarm' ? '/api/swarm/reset' : '/api/mission/reset', { method: 'POST' }); state.time = 0; state.frame = 0; state.passCount = 0; state.running = false; applyPayload(payload, true); $('toggleMission').textContent = 'START MISSION'; setStatus('MISSION RESET COMPLETE', 'success') } catch (error) { setStatus(error.message, 'error') } }; $('testEvent').onclick = triggerTest; $('loadFrame').onclick = () => $('frameInput').click(); $('frameInput').onchange = () => analyzeFrame($('frameInput').files[0]); $('loadDem').onclick = () => $('demInput').click(); $('demInput').onchange = () => loadDem($('demInput').files[0]); $('loadSatellite').onclick = () => $('satelliteInput').click(); $('satelliteInput').onchange = () => loadSatellite($('satelliteInput').files[0]); $('loadChange').onclick = () => { if (!state.changeFiles.previous) $('previousChangeInput').click(); else if (!state.changeFiles.current) $('currentChangeInput').click(); else analyzeChange() }; $('previousChangeInput').onchange = () => { state.changeFiles.previous = $('previousChangeInput').files[0] || null; if (state.changeFiles.previous) $('currentChangeInput').click() }; $('currentChangeInput').onchange = () => { state.changeFiles.current = $('currentChangeInput').files[0] || null; if (state.changeFiles.current) analyzeChange() }; $('uploadDataset').onclick = () => $('datasetInput').click(); $('datasetInput').onchange = () => analyzeDataset($('datasetInput').files[0]); $('exportPacket').onclick = async () => { const format = $('exportFormat').value; const response = await fetch(`/api/mission/export?format=${encodeURIComponent(format)}`); const blob = await response.blob(); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = `kairodristi-field-packet.${format}`; link.click(); setStatus(`${format.toUpperCase()} FIELD PACKET EXPORTED`, 'success') }; document.querySelectorAll('[data-sensor]').forEach(button => { button.onclick = () => selectSensor(button.dataset.sensor) }) }
function animate(now = performance.now()) { requestAnimationFrame(animate); const delta = Math.min(Math.max((now - state.lastAnimationMs) / 1000, 0), .25); state.lastAnimationMs = now; if (state.running) { state.time += delta; if (state.mode === 'single' && !state.detected && !state.detecting && !state.autoDetectionAttempted && state.time > 34) { state.autoDetectionAttempted = true; triggerTest() } if (state.time > Math.max(effectiveSingleRoute().length * 18 + 12, 1) && state.mode === 'single') state.time = 0 } moveDrones(delta); updateUi(); updateOrbit(); renderer.render(scene, camera); cameraRenderer.render(scene, droneCamera) }
async function boot() { try { const [mission, terrain, readiness, swarm] = await Promise.all([requestJson('/api/mission'), requestJson('/api/terrain'), requestJson('/api/readiness'), requestJson('/api/swarm').catch(() => null)]); state.terrain = terrain; state.satellite = mission.satellite_context || null; if (swarm?.initialized) applySwarm(swarm); else applySingle(mission); $('readinessBadge').textContent = `${readiness.model_loaded ? 'YOLO READY' : String(readiness.detector_mode || 'OPENCV').toUpperCase()} · ${readiness.planner_ready ? 'PLANNER READY' : 'NO DEM'}`; $('readinessBadge').className = `readiness-badge ${readiness.model_loaded ? 'ready' : 'fallback'}`; updateDataSourceStatus(); buildTrees(); initInput(); initButtons(); initLayerButtons(); selectSensor('rgb'); updateRenderers(); frameMainView(); state.running = true; $('toggleMission').textContent = 'PAUSE MISSION'; setStatus('LIVE DRONE TRACK ACTIVE', 'success'); state.lastAnimationMs = performance.now(); requestAnimationFrame(animate) } catch (error) { app.innerHTML = `<main class="error-state"><h1>Mission console unavailable</h1><p>${error.message}</p><p>Start the API with <code>py -3.11 -m app.server</code>.</p><button type="button" onclick="location.reload()">RETRY CONNECTION</button></main>` } }
async function refreshAirspace() { state.airspace = await requestJson('/api/airspace').catch(() => ({ source: 'unavailable', available: false, aircraft: [] })); const badge = $('airspaceBadge'); if (badge) { badge.textContent = state.mode === 'swarm' ? 'SWARM · PLANNING ONLY' : 'SIMULATION ONLY'; badge.className = 'readiness-badge fallback' }; drawMinimap() }
boot(); setTimeout(refreshAirspace, 250)
